from typing import Annotated

from fastapi import Depends, FastAPI, Header, HTTPException
from httpx import ASGITransport, AsyncClient
from pydantic import BaseModel

app = FastAPI()
UTILISATEURS = {"jeton-camille": ("camille", "admin"), "jeton-karim": ("karim", "lecteur")}


class Utilisateur(BaseModel):
    pseudo: str
    role: str


async def utilisateur_courant(authorization: Annotated[str, Header()] = "") -> Utilisateur:
    jeton = authorization.removeprefix("Bearer ")
    if jeton not in UTILISATEURS:
        raise HTTPException(401, detail="Authentification requise")
    pseudo, role = UTILISATEURS[jeton]
    return Utilisateur(pseudo=pseudo, role=role)


def exiger_role(*roles: str):
    async def verifier(utilisateur: Annotated[Utilisateur, Depends(utilisateur_courant)]) -> Utilisateur:
        if utilisateur.role not in roles:
            raise HTTPException(403, detail="Droits insuffisants")
        return utilisateur
    return verifier


@app.delete("/clients/{client_id}")
async def supprimer(client_id: int, admin: Annotated[Utilisateur, Depends(exiger_role("admin"))]):
    return {"supprime": client_id, "par": admin.pseudo}


async with AsyncClient(transport=ASGITransport(app=app), base_url="http://test") as client:
    for jeton in ("jeton-camille", "jeton-karim", "inconnu"):
        reponse = await client.delete("/clients/7", headers={"Authorization": f"Bearer {jeton}"})
        print(reponse.status_code, reponse.json())

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse
from httpx import ASGITransport, AsyncClient


class ErreurMetier(Exception):
    statut = 400
    code = "erreur_metier"

    def __init__(self, message):
        self.message = message


class StockInsuffisant(ErreurMetier):
    statut = 409
    code = "stock_insuffisant"


class ProduitInconnu(ErreurMetier):
    statut = 404
    code = "produit_inconnu"


STOCKS = {"STY-01": 3}


def reserver(reference, quantite):  # du code métier, sans HTTP
    if reference not in STOCKS:
        raise ProduitInconnu(f"Produit {reference} inconnu")
    if STOCKS[reference] < quantite:
        raise StockInsuffisant(f"Il ne reste que {STOCKS[reference]} {reference}")
    STOCKS[reference] -= quantite


app = FastAPI()


@app.exception_handler(ErreurMetier)
async def traduire(requete: Request, erreur: ErreurMetier):
    return JSONResponse(status_code=erreur.statut, content={"code": erreur.code, "message": erreur.message})


@app.post("/reservations")
async def reservation(reference: str, quantite: int):
    reserver(reference, quantite)
    return {"restant": STOCKS[reference]}


async with AsyncClient(transport=ASGITransport(app=app), base_url="http://test") as client:
    for reference, quantite in (("STY-01", 2), ("STY-01", 5), ("XXX", 1)):
        reponse = await client.post("/reservations", params={"reference": reference, "quantite": quantite})
        print(reponse.status_code, reponse.json())

