from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from httpx import ASGITransport, AsyncClient
from pydantic import BaseModel

app = FastAPI()
MESSAGES = {"missing": "champ obligatoire", "int_parsing": "nombre entier attendu"}


@app.exception_handler(RequestValidationError)
async def validation(requete: Request, erreur: RequestValidationError):
    champs = {e["loc"][-1]: MESSAGES.get(e["type"], e["msg"]) for e in erreur.errors()}
    return JSONResponse(status_code=422, content={"erreurs": champs})


class Commande(BaseModel):
    produit: str
    quantite: int


@app.post("/commandes")
async def commander(commande: Commande):
    return commande


async with AsyncClient(transport=ASGITransport(app=app), base_url="http://test") as client:
    print((await client.post("/commandes", json={"quantite": "deux"})).json())

